<script setup lang="ts">
import {computed,onMounted,reactive,ref} from 'vue';import {api,fmt,json} from '@/lib/api';import PageHeader from '@/components/PageHeader.vue';import AppModal from '@/components/AppModal.vue';import EmptyState from '@/components/EmptyState.vue';import {Plus,Search} from 'lucide-vue-next';
const items=ref<any[]>([]),open=ref(false),editing=ref<any>(null),search=ref(''),form=reactive<any>({});const filtered=computed(()=>items.value.filter(x=>(x.name+x.sku+(x.category||'')).toLowerCase().includes(search.value.toLowerCase())));async function load(){items.value=await api('/products')}function show(x?:any){editing.value=x||null;Object.assign(form,x||{name:'',sku:'',category:'',referenceProductCost:0,referencePackagingCost:0,notes:''});open.value=true}async function save(){await api(editing.value?`/products/${editing.value.id}`:'/products',json(editing.value?'PATCH':'POST',form));open.value=false;await load()}async function del(x:any){if(confirm(`确定删除 ${x.name}？被库存或订单引用时将无法删除。`)){try{await api(`/products/${x.id}`,{method:'DELETE'});await load()}catch(e:any){alert(e.message)}}}onMounted(load);
</script><template><PageHeader title="商品成本" subtitle="维护 SKU 和采购时使用的参考成本"><el-button type="primary" :icon="Plus" @click="show()">新增商品</el-button></PageHeader><el-card shadow="never"><div class="mb-4 max-w-sm"><el-input v-model="search" :prefix-icon="Search" clearable placeholder="搜索商品、SKU 或品类"/></div><el-table :data="filtered" stripe empty-text="暂无商品"><el-table-column label="商品 / SKU" min-width="200"><template #default="{row}"><b>{{row.name}}</b><div class="text-xs text-slate-400">{{row.sku}}</div></template></el-table-column><el-table-column prop="category" label="品类"/><el-table-column label="产品参考成本"><template #default="{row}">¥ {{fmt(row.referenceProductCost)}}</template></el-table-column><el-table-column label="包材参考成本"><template #default="{row}">¥ {{fmt(row.referencePackagingCost)}}</template></el-table-column><el-table-column label="综合参考成本"><template #default="{row}"><b>¥ {{fmt(Number(row.referenceProductCost)+Number(row.referencePackagingCost))}}</b></template></el-table-column><el-table-column prop="notes" label="备注" show-overflow-tooltip/><el-table-column label="操作" width="140" fixed="right"><template #default="{row}"><el-button link type="primary" @click="show(row)">编辑</el-button><el-button link type="danger" @click="del(row)">删除</el-button></template></el-table-column></el-table></el-card><AppModal :open="open" :title="editing?'编辑商品':'新增商品'" @close="open=false"><el-form :model="form" label-position="top" @submit.prevent="save"><div class="grid gap-x-4 sm:grid-cols-2"><el-form-item label="产品名称" required><el-input v-model="form.name"/></el-form-item><el-form-item label="SKU" required><el-input v-model="form.sku"/></el-form-item><el-form-item label="品类"><el-input v-model="form.category"/></el-form-item><div></div><el-form-item label="参考产品成本/件（CNY）"><el-input-number v-model="form.referenceProductCost" :min="0" :precision="4" class="!w-full" controls-position="right"/></el-form-item><el-form-item label="参考包材成本/件（CNY）"><el-input-number v-model="form.referencePackagingCost" :min="0" :precision="4" class="!w-full" controls-position="right"/></el-form-item><el-form-item label="备注" class="sm:col-span-2"><el-input v-model="form.notes" type="textarea" :rows="3"/></el-form-item></div><div class="flex justify-end gap-2"><el-button @click="open=false">取消</el-button><el-button type="primary" native-type="submit">保存</el-button></div></el-form></AppModal></template>
